/**
 * prisma/seed.ts
 *
 * Repeatable seed script for IEEJAY EATS.
 *
 * How repeatability is achieved
 * ──────────────────────────────
 * 1. Every seed run deletes ALL existing seed data first (via truncate order).
 * 2. Faker is initialised with a fixed seed (12345) so the generated data
 *    is deterministic — two runs produce the same records.
 * 3. Because UUIDs are generated by Prisma (not Faker), records get new UUIDs
 *    on each run, but the volume and content are identical.
 *
 * Running twice is safe: the DELETE step prevents duplicates.
 *
 * Usage
 * ──────
 *   npx tsx prisma/seed.ts
 *   # or via package.json:  npm run seed
 */

