// ─── Helpers ─────────────────────────────────────────────────────────────────

function randomBetween(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomFloat(min: number, max: number, decimals = 2): number {
  return parseFloat((Math.random() * (max - min) + min).toFixed(decimals));
}

function pickRandom<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function pickRandomN<T>(arr: T[], n: number): T[] {
  const shuffled = [...arr].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, n);
}

function nigerianPhone(): string {
  const prefixes = ["0803", "0806", "0810", "0813", "0814", "0816", "0817", "0818", "0819",
    "0701", "0702", "0703", "0704", "0705", "0706", "0708",
    "0901", "0902", "0903", "0904", "0905", "0906", "0907", "0908", "0909",
    "0911", "0912", "0913", "0914", "0915", "0916", "0917", "0918", "0919"];
  return `${pickRandom(prefixes)}${faker.string.numeric(7)}`;
}

function nigerianAddress(): string {
  const streetNumbers = randomBetween(1, 200);
  const streets = [
    "Awolowo Road", "Allen Avenue", "Adeola Odeku Street", "Bode Thomas Street",
    "Broad Street", "Marina Road", "Ahmadu Bello Way", "Independence Avenue",
    "Yakubu Gowon Crescent", "Tafawa Balewa Square", "Wuse Zone", "Maitama District",
    "Lekki Phase 1", "Victoria Island", "Ikorodu Road", "Apapa Road",
    "Trans Amadi Layout", "Rumuola Road", "Old GRA", "New GRA",
    "New Road", "Aggrey Road", "Aba Road", "Elekahia Road",
    "Zaria Road", "Lagos Road", "Kano Road", "Jos Road",
  ];
  return `${streetNumbers} ${pickRandom(streets)}`;
}

// ─── Main seed function ───────────────────────────────────────────────────────

async function main() {
  console.log("🌱 Starting IEEJAY EATS seed...");

  // Delete in FK-safe order
  console.log("🗑️  Clearing existing data...");
  await prisma.orderItem.deleteMany();
  await prisma.order.deleteMany();
  await prisma.customer.deleteMany();
  await prisma.menuItem.deleteMany();
  await prisma.restaurant.deleteMany();
  console.log("   Done.");

  // ── Restaurants ────────────────────────────────────────────────────────────
  console.log("🍽️  Seeding restaurants...");

  // Build enough unique names (300+)
  const allRestaurantNames: string[] = [];
  while (allRestaurantNames.length < 300) {
    for (const base of RESTAURANT_NAMES) {
      const variant = allRestaurantNames.length % 10 === 0
        ? base
        : `${base} ${faker.location.buildingNumber()}`;
      if (!allRestaurantNames.includes(variant)) {
        allRestaurantNames.push(variant);
      }
      if (allRestaurantNames.length >= 300) break;
    }
  }

  const restaurantData = allRestaurantNames.slice(0, 300).map((name) => ({
    name,
    description: faker.lorem.sentences(2),
    address: nigerianAddress(),
    city: pickRandom(NIGERIAN_CITIES),
    phone: nigerianPhone(),
    cuisineType: pickRandom(CUISINE_TYPES),
    rating: randomFloat(2.5, 5.0),
    isOpen: Math.random() > 0.15,
  }));

  await prisma.restaurant.createMany({ data: restaurantData });
  const restaurants = await prisma.restaurant.findMany({ select: { id: true } });
  console.log(`   Created ${restaurants.length} restaurants.`);

  // ── Menu Items ─────────────────────────────────────────────────────────────
  console.log("🥘  Seeding menu items...");

  const menuItemData: {
    restaurantId: string;
    name: string;
    description: string;
    category: string;
    price: number;
    isAvailable: boolean;
  }[] = [];

  for (const restaurant of restaurants) {
    // Each restaurant gets 2–5 items per category present
    const selectedCategories = pickRandomN(MENU_CATEGORIES, randomBetween(4, 8));
    for (const category of selectedCategories) {
      const dishes = NIGERIAN_DISHES[category] ?? [];
      if (dishes.length === 0) continue;
      const count = randomBetween(2, Math.min(4, dishes.length));
      const selected = pickRandomN(dishes, count);
      for (const dish of selected) {
        menuItemData.push({
          restaurantId: restaurant.id,
          name: dish.name,
          description: dish.description,
          category,
          price: randomFloat(dish.minPrice, dish.maxPrice),
          isAvailable: Math.random() > 0.1,
        });
      }
    }
  }

  // Batch insert in chunks of 500 to avoid Prisma limits
  const CHUNK = 500;
  for (let i = 0; i < menuItemData.length; i += CHUNK) {
    await prisma.menuItem.createMany({ data: menuItemData.slice(i, i + CHUNK) });
  }
  const menuItemCount = await prisma.menuItem.count();
  console.log(`   Created ${menuItemCount} menu items.`);

  // ── Customers ──────────────────────────────────────────────────────────────
  console.log("👤  Seeding customers...");

  const usedEmails = new Set<string>();
  const customerData: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    address: string;
  }[] = [];

  while (customerData.length < 300) {
    const firstName = faker.person.firstName();
    const lastName = faker.person.lastName();
    const email = `${firstName.toLowerCase()}.${lastName.toLowerCase()}${customerData.length}@example.com`;
    if (usedEmails.has(email)) continue;
    usedEmails.add(email);
    customerData.push({
      firstName,
      lastName,
      email,
      phone: nigerianPhone(),
      address: `${nigerianAddress()}, ${pickRandom(NIGERIAN_CITIES)}`,
    });
  }

  for (let i = 0; i < customerData.length; i += CHUNK) {
    await prisma.customer.createMany({ data: customerData.slice(i, i + CHUNK) });
  }
  const customers = await prisma.customer.findMany({ select: { id: true } });
  console.log(`   Created ${customers.length} customers.`);

  // ── Orders ─────────────────────────────────────────────────────────────────
  console.log("📦  Seeding orders...");

  // Fetch menu items grouped by restaurant for realistic order items
  const menuItemsByRestaurant = await prisma.menuItem.findMany({
    select: { id: true, restaurantId: true, price: true },
  });
  const menuByRestaurant: Record<string, { id: string; price: number }[]> = {};
  for (const item of menuItemsByRestaurant) {
    if (!menuByRestaurant[item.restaurantId]) menuByRestaurant[item.restaurantId] = [];
    menuByRestaurant[item.restaurantId].push({ id: item.id, price: item.price });
  }

  const orderInserts: {
    customerId: string;
    restaurantId: string;
    status: OrderStatus;
    totalAmount: number;
    deliveryAddress: string;
  }[] = [];

  const orderItemsMap: { orderId: string; menuItemId: string; quantity: number; unitPrice: number }[][] = [];

  // We'll create 500+ orders, but need to do it in two steps (order then items)
  const TARGET_ORDERS = 500;
  const orderTempData: { customerId: string; restaurantId: string; items: { menuItemId: string; quantity: number; unitPrice: number }[]; deliveryAddress: string; status: OrderStatus }[] = [];

  for (let i = 0; i < TARGET_ORDERS; i++) {
    const customer = pickRandom(customers);
    const restaurant = pickRandom(restaurants);
    const restaurantMenu = menuByRestaurant[restaurant.id] ?? [];
    if (restaurantMenu.length === 0) continue;

    const selectedItems = pickRandomN(restaurantMenu, randomBetween(1, Math.min(4, restaurantMenu.length)));
    const items = selectedItems.map((mi) => ({
      menuItemId: mi.id,
      quantity: randomBetween(1, 3),
      unitPrice: mi.price,
    }));
    const totalAmount = parseFloat(items.reduce((sum, it) => sum + it.unitPrice * it.quantity, 0).toFixed(2));

    orderTempData.push({
      customerId: customer.id,
      restaurantId: restaurant.id,
      status: pickRandom(ORDER_STATUSES),
      deliveryAddress: `${nigerianAddress()}, ${pickRandom(NIGERIAN_CITIES)}`,
      items,
    });
  }

  // Insert orders first
  for (const od of orderTempData) {
    const order = await prisma.order.create({
      data: {
        customerId: od.customerId,
        restaurantId: od.restaurantId,
        status: od.status,
        totalAmount: od.items.reduce((s, it) => s + it.unitPrice * it.quantity, 0),
        deliveryAddress: od.deliveryAddress,
      },
    });
    // Collect order items
    orderItemsMap.push(od.items.map((it) => ({ orderId: order.id, ...it })));
  }

  // Insert all order items in chunks
  const allOrderItems = orderItemsMap.flat();
  for (let i = 0; i < allOrderItems.length; i += CHUNK) {
    await prisma.orderItem.createMany({ data: allOrderItems.slice(i, i + CHUNK) });
  }

  const orderCount = await prisma.order.count();
  const orderItemCount = await prisma.orderItem.count();
  console.log(`   Created ${orderCount} orders with ${orderItemCount} order items.`);

  console.log("\n✅ IEEJAY EATS seed complete.");
  console.log(`   Restaurants : ${restaurants.length}`);
  console.log(`   Menu Items  : ${menuItemCount}`);
  console.log(`   Customers   : ${customers.length}`);
  console.log(`   Orders      : ${orderCount}`);
  console.log(`   Order Items : ${orderItemCount}`);
}

main()
  .catch((err) => {
    console.error("❌ Seed failed:", err);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
